import{_ as t,b as a,c as r,g as o}from"./chunks/framework.86O3EbG5.js";const m=JSON.parse('{"title":"程序是怎么跑起来的","description":"","frontmatter":{"title":"程序是怎么跑起来的","subTitle":"程序加载与内存节约","author":"oasis","date":"2026-09-10T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/how-program-works/4.md","filePath":"articles/books/how-program-works/4.md"}'),s={name:"articles/books/how-program-works/4.md"};function p(n,e,i,d,_,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="程序如何运行" tabindex="-1">程序如何运行</h2><p>程序文件存储在硬盘中；执行时先进入内存，CPU 从内存中读取指令和数据来完成取指、译码、执行。</p><p>资料：<a href="https://man7.org/linux/man-pages/man5/elf.5.html" target="_blank" rel="noreferrer">ELF 手册页</a></p><h2 id="如何将程序从磁盘加载进内存" tabindex="-1">如何将程序从磁盘加载进内存</h2><p>对于 C 程序，编译后可得到一个 <code>.out</code> 文件，该文件在 Linux 中是按照 ELF 规范生成的。</p><p>程序加载器会读取 ELF 标准的文件，解析 Program Headers，操作系统为该程序分配虚拟地址空间。</p><p>分配虚拟地址空间，不代表程序被完整地加载进内存。当第一次访问某页时，如果该页不在物理内存中，CPU 会触发缺页异常，内核进行处理：检测访问合法性、从磁盘读取或复用缓存等，更新页表，并重新执行指令。</p><p>（这里需要看 x86 的实现）</p><h2 id="节约内存的方式" tabindex="-1">节约内存的方式</h2><p>通过 DLL 文件共享函数，程序运行时动态链接该文件，多个程序可以同时共用一个 DLL 文件，从而只开辟一块内存空间，节约内存用量。</p><p>通过 <code>stdcall</code> 将清理栈的工作交给被调用方，从而减少调用方编译后产生的重复清理指令。</p>',11)])])}const h=t(s,[["render",p]]);export{m as __pageData,h as default};
